/bin/zsh -lc "cat > work/extract_video.swift <<'SWIFT'
import Foundation
import AVFoundation
import AppKit
let url = URL(fileURLWithPath: CommandLine.arguments[1])
let out = URL(fileURLWithPath: CommandLine.arguments[2], isDirectory: true)
let asset = AVURLAsset(url: url)
let duration = CMTimeGetSeconds(asset.duration)
print(\"DURATION_SECONDS\", duration)
let gen = AVAssetImageGenerator(asset: asset)
gen.appliesPreferredTrackTransform = true
gen.maximumSize = CGSize(width: 1000, height: 1000)
for i in 0..<8 {
 let sec = max(0.3, duration * Double(i) / 8.0)
 do {
  let cg = try gen.copyCGImage(at: CMTime(seconds: sec, preferredTimescale: 600), actualTime: nil)
  let bitmap = NSBitmapImageRep(cgImage: cg)
  if let png = bitmap.representation(using: .png, properties: [:]) {
   let file = out.appendingPathComponent(String(format: \"frame-%02d.png\", i))
   try png.write(to: file)
   print(file.path, sec)
  }
 } catch { print(\"ERROR\", error) }
}
